using System.Text;using System.Text.Json;using HrDataAnalyzer.Models;
namespace HrDataAnalyzer.Services;
public sealed class ReportService
{ public byte[] Csv(IEnumerable<Employee> employees){var sb=new StringBuilder("Id,Name,Department,Role,Location,EmploymentType,HireDate,Salary,PerformanceScore,Active\n");foreach(var e in employees)sb.AppendLine(string.Join(',',new[]{e.Id,e.Name,e.Department,e.Role,e.Location,e.EmploymentType,e.HireDate.ToString("yyyy-MM-dd"),e.Salary.ToString("0.00"),e.PerformanceScore.ToString(),e.Active.ToString()}.Select(Escape)));return Encoding.UTF8.GetBytes(sb.ToString());} static string Escape(string s)=>$"\"{s.Replace("\"","\"\"")}\""; public byte[] Json(IEnumerable<Employee> employees)=>Encoding.UTF8.GetBytes(JsonSerializer.Serialize(employees,new JsonSerializerOptions{WriteIndented=true})); public byte[] Html(IEnumerable<Employee> employees,AnalyticsSummary summary){var sb=new StringBuilder("<!doctype html><html><head><meta charset='utf-8'><title>HR report</title><style>body{font-family:Arial;margin:2rem}table{border-collapse:collapse}td,th{padding:.4rem;border:1px solid #ddd}</style></head><body><h1>HR Data Report</h1>");sb.Append($"<p>{summary.TotalEmployees} employees · {summary.ActiveEmployees} active · Average salary {summary.AverageSalary:C}</p><table><tr><th>Name</th><th>Department</th><th>Role</th><th>Salary</th><th>Performance</th></tr>");foreach(var e in employees)sb.Append($"<tr><td>{System.Net.WebUtility.HtmlEncode(e.Name)}</td><td>{System.Net.WebUtility.HtmlEncode(e.Department)}</td><td>{System.Net.WebUtility.HtmlEncode(e.Role)}</td><td>{e.Salary:C}</td><td>{e.PerformanceScore}</td></tr>");return Encoding.UTF8.GetBytes(sb+"</table></body></html>");}}
